export const metadata = {
  title: "Book Tracker",
  description: "Keep track of books you are reading",
};

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      <body style={{ fontFamily: "system-ui, sans-serif", maxWidth: 720, margin: "0 auto", padding: "24px" }}>
        <header style={{ marginBottom: 24 }}>
          <h1 style={{ margin: 0 }}><a href="/" style={{ textDecoration: "none", color: "inherit" }}>Book Tracker</a></h1>
        </header>
        <main>{children}</main>
      </body>
    </html>
  );
}

import fs from "fs";
import path from "path";

const dataDir = path.join(process.cwd(), "data");
const dataFile = path.join(dataDir, "books.json");

export function ensureDataFile() {
  if (!fs.existsSync(dataDir)) fs.mkdirSync(dataDir, { recursive: true });
  if (!fs.existsSync(dataFile)) fs.writeFileSync(dataFile, JSON.stringify([]));
}

export function getBooks() {
  ensureDataFile();
  try {
    const raw = fs.readFileSync(dataFile, "utf8");
    const parsed = JSON.parse(raw || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function saveBooks(books) {
  ensureDataFile();
  fs.writeFileSync(dataFile, JSON.stringify(books, null, 2));
}

export function getBookById(id) {
  return getBooks().find((b) => b.id === id) || null;
}

export function addBook({ title, author, notes }) {
  const books = getBooks();
  const book = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    title: title.trim(),
    author: author.trim(),
    notes: (notes || "").trim(),
    status: "reading",
    createdAt: new Date().toISOString(),
  };
  books.push(book);
  saveBooks(books);
  return book;
}

export function updateBookStatus(id, status) {
  const books = getBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = status;
  saveBooks(books);
  return book;
}

