        <li key={book.id} style={{ border: "1px solid #ddd", padding: 12, borderRadius: 6, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <a href={`/books/${book.id}`} style={{ fontWeight: 600 }}>{book.title}</a>
            <span> by {book.author}</span>
            {book.status === "finished" && <span style={{ marginLeft: 8, fontSize: 12, background: "#e6ffe6", padding: "2px 6px", borderRadius: 4 }}>Finished</span>}
          </div>
          {book.status === "reading" && (
            <button onClick={() => markFinished(book.id)} style={{ padding: "6px 12px", cursor: "pointer" }}>
              Mark as finished
            </button>
          )}
        </li>
      ))}
    </ul>
  );
}

"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";

export default function AddBookForm() {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");
  const [notes, setNotes] = useState("");
  const [error, setError] = useState("");

  async function onSubmit(e) {
    e.preventDefault();
    setError("");
    if (!title.trim() || !author.trim()) {
      setError("Title and author are required");
      return;
    }
    const res = await fetch("/api/books", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, author, notes }),
    });
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      setError(data.error || "Failed to add book");
      return;
    }
    setTitle("");
    setAuthor("");
    setNotes("");
    router.refresh();
  }

  return (
    <form onSubmit={onSubmit} style={{ display: "grid", gap: 8, maxWidth: 400 }}>
      <label>
        Title
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Title"
          required
          style={{ display: "block", width: "100%", padding: 8, marginTop: 4 }}
        />
      </label>
      <label>
        Author
        <input
          value={author}
          onChange={(e) => setAuthor(e.target.value)}
          placeholder="Author"
          required
          style={{ display: "block", width: "100%", padding: 8, marginTop: 4 }}
        />
      </label>
      <label>
        Notes
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Notes"
          rows={3}
          style={{ display: "block", width: "100%", padding: 8, marginTop: 4 }}
        />
      </label>
      {error && <p style={{ color: "red" }}>{error}</p>}
      <button type="submit" style={{ padding: "8px 16px", cursor: "pointer" }}>Add book</button>
    </form>
  );
}

import { getBooks } from "../lib/books.js";
import AddBookForm from "./AddBookForm.js";
import BookList from "./BookList.js";

export const dynamic = "force-dynamic";

export default function Home() {
  const books = getBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  return (
    <div>
      <section style={{ marginBottom: 32 }}>
