import { getBooks, addBook } from "../../../lib/books.js";

export async function GET() {
  const books = getBooks();
  return Response.json(books);
}

export async function POST(request) {
  let body;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Invalid JSON" }, { status: 400 });
  }
  const { title, author, notes } = body || {};
  if (!title || !title.trim() || !author || !author.trim()) {
    return Response.json({ error: "Title and author are required" }, { status: 400 });
  }
  const book = addBook({ title, author, notes });
  return Response.json(book, { status: 201 });
}

import { getBookById, updateBookStatus, getBooks, saveBooks } from "../../../../lib/books.js";

export async function GET(request, { params }) {
  const { id } = await params;
  const book = getBookById(id);
  if (!book) return Response.json({ error: "Not found" }, { status: 404 });
  return Response.json(book);
}

export async function PATCH(request, { params }) {
  const { id } = await params;
  let body;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Invalid JSON" }, { status: 400 });
  }
  const { status } = body || {};
  if (status !== "finished" && status !== "reading") {
    return Response.json({ error: "Invalid status" }, { status: 400 });
  }
  const book = updateBookStatus(id, status);
  if (!book) return Response.json({ error: "Not found" }, { status: 404 });
  return Response.json(book);
}

